// ═══ FULL CONSTRUCTOR ═══
ThreadPoolExecutor pool = new ThreadPoolExecutor(
    5,                                   // corePoolSize: min 5 workers
    10,                                  // maximumPoolSize: max 10 under burst
    60, TimeUnit.SECONDS,                // keepAliveTime: idle non-core die after 60s
    new LinkedBlockingQueue<>(100),      // workQueue: bounded! 100 tasks max!
    r -> {                               // threadFactory: named threads!
        Thread t = new Thread(r, "payment-worker-" + counter.incrementAndGet());
        t.setDaemon(false);
        return t;
    },
    new ThreadPoolExecutor.CallerRunsPolicy()  // rejectionHandler: back-pressure!
);

// ═══ TASK SUBMISSION FLOW ═══
// 1. submit(task) → workers < corePoolSize(5)? → CREATE new core worker!
// 2. workers ≥ 5? → offer(task) to workQueue
// 3. Queue accepts? → task QUEUED, waiting for free worker
// 4. Queue FULL (100 tasks)? → workers < maxPoolSize(10)? → CREATE non-core worker!
// 5. Workers = 10 AND queue FULL? → REJECTION HANDLER fires!

// ═══ FOUR REJECTION POLICIES ═══
// 1. AbortPolicy (DEFAULT): throw RejectedExecutionException!
new ThreadPoolExecutor.AbortPolicy();
// Use: when task loss is UNACCEPTABLE. Caller handles the exception.
// Risk: caller must catch and handle!

// 2. CallerRunsPolicy: caller thread executes the task!
new ThreadPoolExecutor.CallerRunsPolicy();
// Use: BEST for back-pressure! Slows down the submitter naturally.
// The submitting thread is busy executing → can't submit more → natural throttle!
// Risk: caller thread blocked during execution!

// 3. DiscardPolicy: silently drop the task!
new ThreadPoolExecutor.DiscardPolicy();
// Use: when losing tasks is acceptable (monitoring, optional logging)
// Risk: SILENT data loss! No exception! No log! DANGEROUS!

// 4. DiscardOldestPolicy: drop the OLDEST queued task, retry the new one!
new ThreadPoolExecutor.DiscardOldestPolicy();
// Use: when latest data is more important than old (real-time updates)
// Risk: oldest task silently lost!

// ═══ PRODUCTION CONFIGURATION ═══
// IO-bound: core=20, max=50, queue=1000, keepAlive=60s
// CPU-bound: core=cores, max=cores, queue=100, keepAlive=0
// NEVER: unbounded queue (OOM!) or unbounded max (thread explosion!)
