package com.bank.tpe;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class TPEParametersTest {

    // ═══ Task flow: core → queue → max → reject ═══
    @Test
    void taskFlow_coreQueueMaxReject() throws InterruptedException {
        AtomicInteger rejected = new AtomicInteger(0);

        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            2, 4, 60, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(3),  // queue capacity = 3!
            Executors.defaultThreadFactory(),
            (r, executor) -> rejected.incrementAndGet()  // custom rejection
        );

        // Submit 10 tasks (each sleeps 500ms):
        for (int i = 0; i < 10; i++) {
            try {
                pool.submit(() -> {
                    try { Thread.sleep(500); } catch (InterruptedException e) { }
                });
            } catch (RejectedExecutionException e) { rejected.incrementAndGet(); }
        }

        Thread.sleep(100);
        System.out.println("Pool size: " + pool.getPoolSize());      // up to 4 (max)
        System.out.println("Queue size: " + pool.getQueue().size());  // up to 3
        System.out.println("Rejected: " + rejected.get());            // remaining!
        // 4 workers + 3 queued = 7 accepted. 3 rejected!

        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
    }

    // ═══ CallerRunsPolicy: back-pressure ═══
    @Test
    void callerRunsPolicy_backPressure() throws InterruptedException {
        AtomicReference<String> callerThread = new AtomicReference<>();

        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            1, 1, 0, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(1),
            Executors.defaultThreadFactory(),
            new ThreadPoolExecutor.CallerRunsPolicy()
        );

        // Fill: 1 worker + 1 queued = 2 tasks
        pool.submit(() -> { try { Thread.sleep(500); } catch (InterruptedException e) { } });
        pool.submit(() -> { try { Thread.sleep(500); } catch (InterruptedException e) { } });

        // 3rd task: worker busy + queue full → CallerRunsPolicy!
        pool.submit(() -> callerThread.set(Thread.currentThread().getName()));

        Thread.sleep(100);
        // CallerRuns: task executed on MAIN thread (or test thread)!
        if (callerThread.get() != null) {
            System.out.println("Caller ran on: " + callerThread.get());
        }
        pool.shutdown();
        pool.awaitTermination(10, TimeUnit.SECONDS);
    }

    // ═══ Custom thread factory: named threads ═══
    @Test
    void customThreadFactory_namedThreads() throws InterruptedException {
        AtomicInteger counter = new AtomicInteger(0);
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            2, 2, 0, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(10),
            r -> new Thread(r, "payment-worker-" + counter.incrementAndGet())
        );

        AtomicReference<String> name = new AtomicReference<>();
        pool.submit(() -> name.set(Thread.currentThread().getName()));
        Thread.sleep(100);

        assertThat(name.get()).startsWith("payment-worker-");
        pool.shutdown();
    }

    // ═══ keepAliveTime: non-core workers die when idle ═══
    @Test
    void keepAlive_nonCoreWorkersDie() throws InterruptedException {
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            1, 3, 1, TimeUnit.SECONDS,  // keepAlive = 1 second!
            new LinkedBlockingQueue<>(1)
        );

        // Cause max workers to be created:
        for (int i = 0; i < 5; i++) {
            pool.submit(() -> { try { Thread.sleep(100); } catch (InterruptedException e) { } });
        }
        Thread.sleep(200);
        int peakSize = pool.getPoolSize();
        System.out.println("Peak pool size: " + peakSize);  // up to 3!

        // Wait for keepAlive to expire:
        Thread.sleep(2000);
        System.out.println("After keepAlive: " + pool.getPoolSize());  // back to 1 (core)!
        assertThat(pool.getPoolSize()).isLessThanOrEqualTo(1);

        pool.shutdown();
    }
}
